import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def read_csv_file(filepath):
    """Read CSV file and return list of dicts."""
    data = []
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            data.append(row)
    return data

def excel_serial_to_date(serial):
    """Convert Excel serial number to YYYY-MM-DD string."""
    if not serial:
        return None
    try:
        # Excel's epoch is 1899-12-30 (or 1900-01-00)
        base = datetime(1899, 12, 30)
        days = int(float(serial))
        date = base + timedelta(days=days)
        return date.strftime('%Y-%m-%d')
    except:
        return None

def process_packet(packet_dir, manifest):
    """Main processing function."""
    # Load manifest
    with open(manifest, 'r') as f:
        manifest_data = json.load(f)

    pairs = manifest_data['pairs']
    facts = manifest_data['facts']

    # Map rule_id to its facts
    rule_facts = {}
    for rule_id, fact_list in facts.items():
        rule_facts[rule_id] = fact_list

    # Group pairs by rule_id and entity
    entity_data = {}
    for pair in pairs:
        rule_id, entity = pair.split('::')
        if rule_id not in entity_data:
            entity_data[rule_id] = {}
        entity_data[rule_id][entity] = {}

    # Read all CSV files in packet directory
    packet_path = Path(packet_dir)
    csv_files = list(packet_path.glob('*.csv'))

    # Process each CSV file
    for csv_file in csv_files:
        filename = csv_file.stem  # Without extension
        data = read_csv_file(csv_file)

        # Process each row in the CSV
        for row in data:
            case_number = row.get('CASE_NUMBER', '').strip()
            if not case_number:
                continue

            # Check each rule to see if this entity is needed
            for rule_id, entities in entity_data.items():
                if case_number in entities:
                    # Handle lca.wage_105 rule
                    if rule_id == 'lca.wage_105':
                        # Offered wage from WAGE_RATE_OF_PAY_FROM
                        offered_wage = row.get('WAGE_RATE_OF_PAY_FROM', '').strip()
                        if offered_wage:
                            offered_wage = offered_wage.replace(',', '')
                            try:
                                offered_wage = str(float(offered_wage))
                            except:
                                offered_wage = None

                        # Prevailing wage from PREVAILING_WAGE
                        prevailing_wage = row.get('PREVAILING_WAGE', '').strip()
                        if prevailing_wage:
                            prevailing_wage = prevailing_wage.replace(',', '')
                            try:
                                prevailing_wage = str(float(prevailing_wage))
                            except:
                                prevailing_wage = None

                        # Store values
                        if 'offered wage' not in entities[case_number]:
                            entities[case_number]['offered wage'] = []
                        if offered_wage is not None:
                            entities[case_number]['offered wage'].append((offered_wage, filename))

                        if 'prevailing wage' not in entities[case_number]:
                            entities[case_number]['prevailing wage'] = []
                        if prevailing_wage is not None:
                            entities[case_number]['prevailing wage'].append((prevailing_wage, filename))

                    # Handle lca.three_years rule
                    elif rule_id == 'lca.three_years':
                        # Begin date from BEGIN_DATE
                        begin_date_raw = row.get('BEGIN_DATE', '').strip()
                        begin_date = excel_serial_to_date(begin_date_raw) if begin_date_raw else None

                        # End date from END_DATE
                        end_date_raw = row.get('END_DATE', '').strip()
                        end_date = excel_serial_to_date(end_date_raw) if end_date_raw else None

                        # Store values
                        if 'begin date' not in entities[case_number]:
                            entities[case_number]['begin date'] = []
                        if begin_date is not None:
                            entities[case_number]['begin date'].append((begin_date, filename))

                        if 'end date' not in entities[case_number]:
                            entities[case_number]['end date'] = []
                        if end_date is not None:
                            entities[case_number]['end date'].append((end_date, filename))

    # Build final result
    result = {}
    for pair in pairs:
        rule_id, entity = pair.split('::')
        fact_results = {}

        for fact_name in rule_facts[rule_id]:
            values = entity_data.get(rule_id, {}).get(entity, {}).get(fact_name, [])

            if not values:
                fact_results[fact_name] = "ABSENT"
            else:
                # Check for conflicts
                unique_values = {}
                for value, doc in values:
                    if value not in unique_values:
                        unique_values[value] = doc
                    elif unique_values[value] != doc:
                        # Different documents have different values = conflict
                        unique_values[value] = "MULTIPLE_DOCS"

                if len(unique_values) == 1:
                    # Single unique value
                    value, doc = list(unique_values.items())[0]
                    if doc == "MULTIPLE_DOCS":
                        fact_results[fact_name] = "CONFLICT"
                    else:
                        fact_results[fact_name] = [value, doc]
                else:
                    # Multiple different values = conflict
                    fact_results[fact_name] = "CONFLICT"

        result[pair] = fact_results

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_file = sys.argv[2]

    result = process_packet(packet_dir, manifest_file)
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
