                    else:
                        result[pair][fact_name] = 'ABSENT'

                elif fact_name == 'prevailing wage':
                    if row:
                        value = row.get('PREVAILING_WAGE')
                        if value and value.strip():
                            try:
                                value = value.replace(',', '')
                                result[pair][fact_name] = [str(float(value)), 'lca_disclosure']
                            except (ValueError, AttributeError):
                                result[pair][fact_name] = 'ABSENT'
                        else:
                            result[pair][fact_name] = 'ABSENT'
                    else:
                        result[pair][fact_name] = 'ABSENT'

            elif rule_id == 'lca.three_years':
                if fact_name == 'begin date':
                    if row:
