import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def read_csv_file(packet_dir, filename):
    """Read CSV file and return list of dicts."""
    filepath = os.path.join(packet_dir, filename)
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)

def excel_date_to_iso(excel_date_str):
    """Convert Excel serial date to ISO format YYYY-MM-DD."""
    if not excel_date_str:
        return None
    try:
        # Excel dates are days since 1899-12-30 (with 1900 leap year bug)
        # Python's datetime starts from 1899-12-30
        days = int(float(excel_date_str))
        base_date = datetime(1899, 12, 30)
        result_date = base_date + timedelta(days=days)
        return result_date.strftime('%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def process_packet(packet_dir, manifest):
    """Process the packet according to manifest."""
    # Read the LCA disclosure file
    lca_data = read_csv_file(packet_dir, "lca_disclosure.csv")

    # Create a mapping from CASE_NUMBER to row data
    case_map = {}
    for row in lca_data:
        case_num = row.get('CASE_NUMBER')
        if case_num:
            case_map[case_num] = row

    # Initialize result dictionary
    result = {}

    # Process each pair in manifest
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::')

        # Initialize facts for this pair
        facts_result = {}

        # Get the row for this entity
        row = case_map.get(entity)

        # Process based on rule_id
        if rule_id == 'lca.wage_105':
            # Offered wage from WAGE_RATE_OF_PAY_FROM
            offered_wage = row.get('WAGE_RATE_OF_PAY_FROM') if row else None
            if offered_wage and offered_wage.strip():
                facts_result['offered wage'] = [offered_wage, "lca_disclosure"]
            else:
                facts_result['offered wage'] = "ABSENT"

            # Prevailing wage from PREVAILING_WAGE
            prevailing_wage = row.get('PREVAILING_WAGE') if row else None
            if prevailing_wage and prevailing_wage.strip():
                facts_result['prevailing wage'] = [prevailing_wage, "lca_disclosure"]
            else:
                facts_result['prevailing wage'] = "ABSENT"

        elif rule_id == 'lca.three_years':
            # Begin date from BEGIN_DATE
            begin_date_raw = row.get('BEGIN_DATE') if row else None
            if begin_date_raw and begin_date_raw.strip():
                begin_date_iso = excel_date_to_iso(begin_date_raw)
                if begin_date_iso:
                    facts_result['begin date'] = [begin_date_iso, "lca_disclosure"]
                else:
                    facts_result['begin date'] = "ABSENT"
            else:
                facts_result['begin date'] = "ABSENT"

            # End date from END_DATE
            end_date_raw = row.get('END_DATE') if row else None
            if end_date_raw and end_date_raw.strip():
                end_date_iso = excel_date_to_iso(end_date_raw)
                if end_date_iso:
                    facts_result['end date'] = [end_date_iso, "lca_disclosure"]
                else:
                    facts_result['end date'] = "ABSENT"
            else:
                facts_result['end date'] = "ABSENT"

        result[pair] = facts_result

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Read manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Process packet
    result = process_packet(packet_dir, manifest)

    # Output result as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
